use std::{fs,path::Path,collections::BTreeMap,process::Command};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-across8";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("native/result.json"))["status"],"complete");assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),112);let a=read(r.join("native/probe/artifacts.json"));let binary=a["binary"].as_str().unwrap();let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("source-pins.json"))).unwrap();for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}assert_eq!(hash(binary),a["binary_sha256"].as_str().unwrap());add(binary,&mut pins);
 for p in [r.join("prepare.rs"),r.join("prepare"),r.join("native-plan.json"),r.join("native/result.json"),r.join("native/probe/artifacts.json"),r.join("source-audit.json"),Path::new("/tmp/zopro-xtask-fast-screen-target/release/xtask").to_path_buf(),Path::new("/usr/bin/perf").to_path_buf()]{add(p,&mut pins);}
 let mut cases=Vec::new();for groups in [1,16]{for c in [false,true]{for rev in [false,true]{for ragged in [false,true]{cases.push(json!({"name":format!("g{groups}-c{}-r{}-h{}",u8::from(c),u8::from(rev),u8::from(ragged)),"groups":groups,"c":u8::from(c).to_string(),"reverse":u8::from(rev).to_string(),"ragged":u8::from(ragged).to_string(),"iterations":if groups==1{1000}else{64}}));}}}}assert_eq!(cases.len(),16);
 let mut jobs=Vec::new();let mut steps=Vec::new();for block in 0..7{for(i,case)in cases.iter().enumerate(){let mut modes=vec!["control-a","control-b","batch"];modes.rotate_left((block+i)%3);if block%2==1{modes.reverse();}for mode in modes{let name=format!("b{block}-{}-{mode}",case["name"].as_str().unwrap());let argv=vec![json!("taskset"),json!("-c"),json!("2"),json!(binary),json!(case["groups"].to_string()),case["c"].clone(),case["reverse"].clone(),case["ragged"].clone(),json!(mode),json!(case["iterations"].to_string())];steps.push(json!({"kind":"command","name":name,"argv":argv,"timeout_seconds":600}));jobs.push(json!({"phase":"latency","name":name,"block":block,"case":case,"mode":mode}));}}}
 for mode in ["control-a","control-b","batch"]{let p=r.join("profiles").join(mode);fs::create_dir_all(&p).unwrap();for file in ["ctl","ack"]{assert!(Command::new("mkfifo").arg(p.join(file)).status().unwrap().success());}let data=p.join("perf.data");let control=format!("--control=fifo:{},{}",p.join("ctl").display(),p.join("ack").display());let name=format!("profile-{mode}");
 steps.push(json!({"kind":"command","name":name,"argv":["sudo","-n","/usr/bin/perf","record","--no-buildid-cache","--clockid","mono","--delay=-1",control,"-e","cycles:u","-F","999","-o",data,"--","sudo","-n","-u","ubuntu","env",format!("ZOPRO_BENCH_PERF_CTL={}",p.join("ctl").display()),format!("ZOPRO_BENCH_PERF_ACK={}",p.join("ack").display()),"taskset","-c","2",binary,"16","0","0","1",mode,"2000"],"timeout_seconds":600}));jobs.push(json!({"phase":"profile","name":name,"mode":mode,"groups":16,"iterations":2000}));}
 for mode in ["control-a","control-b","batch"]{let data=r.join("profiles").join(mode).join("perf.data");steps.push(json!({"kind":"command","name":format!("samples-{mode}"),"argv":["sudo","-n","/usr/bin/perf","script","--show-lost-events","-i",data,"-F","comm,pid,tid,time,event,ip,sym,period"],"timeout_seconds":180}));steps.push(json!({"kind":"command","name":format!("report-{mode}"),"argv":["sudo","-n","/usr/bin/perf","report","--stdio","--header","--percent-limit","0","-i",data],"timeout_seconds":180}));}
 save(r.join("cases.json"),&json!(cases));save(r.join("jobs.json"),&json!(jobs));add(r.join("cases.json"),&mut pins);add(r.join("jobs.json"),&mut pins);for(p,h)in &pins{assert_eq!(&hash(p),h);}save(r.join("measurement-pins.json"),&json!(pins));save(r.join("measurement-plan.json"),&json!({"version":1,"source_pins":r.join("measurement-pins.json"),"steps":steps}));println!("Frozen336latency processes then3profiles;0SDK/Gnark;prior6946unchanged");
}
